mapper.update:
UPDATE tc_payment_receipt SET refund_reserved_amount=refund_reserved_amount+#{amount},updated_at=#{now},version=version+1
WHERE tenant_id=#{tenant} AND id=#{receipt} AND currency=#{currency}
  AND amount-refunded_amount-refund_reserved_amount >= #{amount}

UPDATE tc_payment_refund_hold SET state='SUCCEEDED',provider_refund_no=#{provider},provider_succeeded_at=#{occurred},
  confirmed_at=#{now},evidence_ref=#{evidence},updated_at=#{now}
WHERE tenant_id=#{tenant} AND refund_no=#{refund} AND state IN ('HELD','SUBMITTED')
